INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p987063-me203', 'stk-metallic', 'ME 203', 'info', '{"desc": "http://www.mediafire.com/?3m74qk6inm8mg8h\nهالسلايدات أعتبرها تغني عن شرح الدكتور وعن أمثلة الكتاب …\n\nمن ناحية الكورس فأنا أشوفه امتع كورس درسته بالجامعة … طبعا اذا حليت اسئلة الهومووك وزيادة اسئلة عليها فانت بتضمن قريد عالي جدا ان شاء الله…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203-thermodynamics-i/120732/2", "user": "METALLIC", "ts": 1329311271000, "tid": 120732, "pn": 2}}', 1329311271000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p987082-me203', 'stk-user5216', 'ME 203', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nجودة المقرر بشكل عام : ممتازة لكن تشابتر 1 و 2 مالهم دخل والمفترض يتم حذفهم من المقرر\n\nالمواضيع التي يغطيها المقرر : قانون حفظ الطاقة + النظام المغلق والمفتوح + الانتروبي\n\nالكتاب المستخدم للمقرر : جيدا جدا\n\nالأسئلة والأمثلة المستخدمة في المقرر : كافيه وتغنى حتى عن الاولد اقزامزز\n\nطريقة دراسة المقرر :\n1 - قراءة الكتاب ( واستيعاب القوانين وتعريفاتها )\n2 - فهم الامثلة وطريقة الحل\n3 - حل اسئلة الهومورك\n4 - حل اسئلة اضافيه تشبه اسئلة الهومورك لاستيعاب طريقة الحل\n5 - الاولد اقزامزز\n\n, وبالتوفيق ,", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203-thermodynamics-i/120732/3", "user": "user5216", "ts": 1329313022000, "tid": 120732, "pn": 3}}', 1329313022000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1056733-me203', 'stk-user5430', 'ME 203', 'info', '{"desc": "جودة المقرر بشكل عام\n\nالمادة تعتبر من امتع واسهل مواد التخصص … تعطي الاساسيات في علم الفلود\nو تطبيقات كثيرة في ارض الواقع\n\nالكتاب المستخدم للمقرر\n\nجيد جدآ … الامثلة ممتآزة و فيه عدد كبيرة من اسئلة نهاية الشابتر\n\nنصائح :\n\n- حاول تختار دكتور ممتاز بالشرح مثل ( الشرقاوي , وائل احمد , السرخي … ) لان مواد الفلود تعتمد عليها .\n- حل الهومورك بنفسك … اذا ضبطت الهومورك اضمن لك على الاقل b+\n- منهج المادة قصير , ولكنها تحتاج حل اسئلة كثيرة\n\nبالتوفيق 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203-thermodynamics-i/120732/4", "user": "user5430", "ts": 1339963470000, "tid": 120732, "pn": 4}}', 1339963470000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1143663-me203', 'stk-user4665', 'ME 203', 'info', '{"desc": "شباب بالنسبة للقريدات\nكم تقريبا راح يكون الرينج للقريدات\nيعني كم البي والبي + والسي والسي +\nتقريبا يعني من واقع تجربتكم او اللي تعرفونه عن المادة\n\nلا هنتو", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203-thermodynamics-i/120732/8", "user": "user4665", "ts": 1355707656000, "tid": 120732, "pn": 8}}', 1355707656000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1171521-me203', 'stk-abu_abdullah', 'ME 203', 'info', '{"desc": "-\n\nالمادة سهلة وتعتبر هي مدخلك لمواد الفلويد في التخصص …\nقوانينها بسيطة و تنحفظ بسرعة …\n\nوالهوموورك مهم جداً … أذكر في ترمنا قبل سنتين جابوا سؤال نسخ لصق من الهوموورك لنا !!\n\nموفقين 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203-thermodynamics-i/120732/10", "user": "Abu_Abdullah", "ts": 1359355163000, "tid": 120732, "pn": 10}}', 1359355163000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1303167-me203', 'stk-user9360', 'ME 203', 'info', '{"desc": "خريطة ذهنية\n\nشباب هذي خريطة ذهنية للثيرمو بشكل عام ممكن تفيدكم\nأتمنى لكم التوفيق و الدرجات العالية في الدنيا و الأخرة\nhttp://skfupm.kfupm.edu.sa/vb/showthread.php?t=116001", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203-thermodynamics-i/120732/12", "user": "user9360", "ts": 1386612806000, "tid": 120732, "pn": 12}}', 1386612806000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1381735-me203', 'stk-abo_ali', 'ME 203', 'info', '{"desc": "جودة المقرر بشكل عام\nجميل وجدن مهم لأي مهندس , مش لازم يكون ميكانيكي علشان يعرف كيف مبدا عمل المكيفات والثلاجات والسخانات والمحركات والتربينات والكمبرسرات وغيرها من الامور ,\n\nالمواضيع التي يغطيها المقرر\nهههه , ذكرتها فوق هع\nيغطي القانون الاول والثاني للثيرموداينامكس 🙂\n\nالكتاب المستخدم للمقرر\nما اذكر وشسمه , لكن كتاب جميل لكن طويل في نفس الوقت 😦\n\nالأسئلة والأمثلة المستخدمة في المقرر\nمناسبه علشان تفتح مخك , + السليوشن موجود فراح ترتاح وانت تحل 🙂\n\nمدى فائدته في الناحية التطبيقية\nجدن مفيييييييييد , كثير من الامور سوف تتضح لك لمن تخلص من الكورس ذا 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203-thermodynamics-i/120732/16", "user": "Abo_Ali", "ts": 1403435332000, "tid": 120732, "pn": 16}}', 1403435332000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1390246-me203', 'stk-ahmad-ali', 'ME 203', 'info', '{"desc": "جودة المقرر بشكل عام\nبالنسبة للصعوبة فالكورس سهل الى متوسط والكتاب المستخدم ممتاز جداً لكن فيه كلام كثير\nالكونسبت فيه واضح وامثلته مفيدة\nلكن سلايدات الدكتور السرخي افضل\n\nالمواضيع التي يغطيها المقرر\nاول شابترين شاطحين شوي عن الحرارة والضغط وحفظ الطاقة واشياء اساسية\nشابتر 3 اهم شابتر لانه اساسيات قرائة الجداول ( طبعا المادة كلها تعتمد على استخراج الارقام من الجداول)\nبقية الشباتر من 4 الى 6 عن الـclosed system and open system و شوية عن الـcycles تشبه فيزكس 101\nشابتر الـ7 عن الانتروبي هذا اصعب شابتر\n\nمدى فائدته في الناحية التطبيقية\nجداً مفيد وخصوصاً انه بعض الدروس تتكلم عن اجهزة مثل الكومبرسر والتوربين وحاجات نلمسها في الواقع\nفحلو انك تكون عارف مبداً عملها\n\nطريقة الـA+\nافهم من الكتاب او سلايدات السرخي واختبر فهمك بحل الامثلة ( ضروري تكون فاهم كل الامثلة لانها تغطي افكار كثيرة)\nحل اسئلة الهومورك وافهمها مو بس نسخ لصق من السوليشن\nحل اسئلة مشابهة او اللي تحس ان فيها افكار\n\nنصيحة : لا تضيع الكلاس تيست او المياجر لان مادة الفاينل صعبة وخصوصاً ان كل المادة داخلة بالفاينل والطالب بيكون مشغول في نهاية السمستر", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203-thermodynamics-i/120732/17", "user": "ahmad-ali", "ts": 1408210493000, "tid": 120732, "pn": 17}}', 1408210493000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1421689-me203', 'stk-user5535', 'ME 203', 'info', '{"desc": "Term 141\n\nأخذت المادة مع د. أحمد شاهين ، أنا عن نفسي ما هضمت الكورس مع إني كنت ماشي معاه في الشرح ، خصوصا لما تجي تحل المسائل ، ياخي ممكن تفترض أكثر من افتراض و كان هذا الشي معقدني ، و المشكلة إني أجيب أم أم العيد في المياجر بسبب هذا الشيء ، ميجر ون أخذت أسوأ درجة ممكن أتخيلها مع إني استعديت له استعداد غير طبيعي ، و السبب إني افترضت افتراض خاطئ\n\nالكورس أسمع كثير يقولون سهل ، لكن بما إني طالب كنترول فالمادة هاذي ما تفتح لنا أي شيء و الفائدة منها هي تفهم كيف يشتغل الكومبروسور و التوربين و الأدوات ذي ، غيرها أشوف إنها بالنسبة لنا مضيعة وقت 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203-thermodynamics-i/120732/18", "user": "user5535", "ts": 1422028934000, "tid": 120732, "pn": 18}}', 1422028934000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1424284-me203', 'stk-user8581', 'ME 203', 'info', '{"desc": "جودة المقرر بشكل عام :\n\n- المادة يمكن تكون سهلة بالنسبة \" للميكانيكال \" او متوسطة بالنسبة للطلاب من التخصصات الثانية خصوصا الي مالهم علاقة بهذي المادة على سبيل المثال طلاب الكنترول . لكن بشكل عام مقدور عليها ولو تبي تنزلها بالصيف فنزل مادة ثانية من مستواها او اقل بشوي … لاتنزلها لحالها في الصيف مايستاهل تنزل صيفي بس عشان الثيرمو**.**\n\n- الكتاب ممتاز جدا خصوصا الامثلة + الاسئلة و الـ summary في نهاية كل شابتر حاول تحل الامثلة والهوموركات مهمة جدا . الكتاب فيه شوي هذرة لكن لو تقدر تحدد الاشياء المهمة في كل صفحة هالشي راح يسهل عليك المذاكرة للمياجر والفاينل بالتحديد .\n\n- المادة مب طويلة لكن لو تسوي ملخص لك بالقوانين وبعض الملاحضات قبل كل الميجر هالشي راح يفيدك في الفانيل لأنه غالبا يكون comprehensive والي يبقى عليك بس هو حل امثلة واسئلة**.**\n\nالمواضيع التي يغطيها المقرر\n\n:Chapter 1 : INTRODUCTION AND BASIC CONCEPTS\nChapter 2: ENERGY, ENERGY TRANSFER, AND GENERAL ENERGY ANALYSIS\nChapter 3: PROPERTIES OF PURE SUBSTANCES\nChapter 4: ENERGY ANALYSIS OF CLOSED SYSTEMS\nChapter 5: MASS AND ENERGY ANALYSIS OF CONTROLVOLUMES\nChapter 6: THE SECOND LAW OF THERMODYNAMICS\nChapter 7: ENTROPY\n\nأول شابترين مالهم علاقة وتقريبا كلها اساسيات واشياء ماخذينها في الفزكس أهم شابترين هم 7 وهو عن الانتروبي\nوشابتر 3 عشان تعرف كيف تستخدم الجداول\n\n+ يمكن تحتاج الـ Interpolation هذا شرح لواحد من طلاب الجامعة الله يجزاه خير\n**https://www.youtube.com/watch?v=vmj0Ee_99qA**", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203-thermodynamics-i/120732/19", "user": "user8581", "ts": 1439892428000, "tid": 120732, "pn": 19}}', 1439892428000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1425922-me203', 'stk-tomoo', 'ME 203', 'info', '{"desc": "كيف طريقه مذاكرتها\nهل من السلايدات او من الكتاب افضل\nوالاسئله اللي بالنهايه مره كثيره صعب الواحد يحلها\nاذا فيه اولد اكرام او شي ياليت تعطونا\nأي نصائح\nوشكرا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203-thermodynamics-i/120732/21", "user": "TOMOO", "ts": 1440619105000, "tid": 120732, "pn": 21}}', 1440619105000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1425935-me203', 'stk-the_lion013', 'ME 203', 'info', '{"desc": "حسب سلبس 151 للثيرمو203, المياجر كومن.\n\nEvaluation:\nIn-class Test (By each instructor, on chapters 1, 2, and 3) 10 % (Sunday, October 11, 2015; In Class)\n\nMajor Exam I (Common, on chapters 3, 4 and 5) 20 % (Wednesday, November 04, 2015 @ 5:30-8:00PM)\n\nMajor Exam II (Common, on chapters 5, 6 and 7) 20 % (Tuesday, December 01, 2015 @ 5:30-8:00PM)\n\nQuizzes (at least 3) 15% (Quiz #1 = 5%, on Sunday, October 4, 2015)\n\nHomework (7 assignments, one on each chapter) 5 %\n\nFinal Exam (comprehensive) 30 % (07:00 PM on Sunday: December 20, 2015)", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203-thermodynamics-i/120732/23", "user": "The_lion013", "ts": 1440623441000, "tid": 120732, "pn": 23}}', 1440623441000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1453837-me203', 'stk-kfupm76', 'ME 203', 'info', '{"desc": "م اخذتها صيف لكن اشوف المادة هذي ي انك تجيب D او انك تجيب A+\n\nالمادة جدا بسيييطة وبعض الاحيان يكون الهوموورك اصعب من الميجر , تقريبا افكار الماده ماهي كثيره , اهم تشابتر فيها هوا 3 اذا فهمته مضبوط انا اضمنلك المادة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203-thermodynamics-i/120732/33", "user": "kfupm76", "ts": 1468538985000, "tid": 120732, "pn": 33}}', 1468538985000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1522397-me203', 'stk-nasalmz', 'ME 203', 'info', '{"desc": "term 191\nمن اسهل و امتع مواد التخصص.\n\nطبعا الكونسبت ف الكورس مره سهل ولازم تطبق عن طريق حلك للهومورك.\nالمياجر كومن وسهالات اذا انك مدرك الهومورك وفاهم الكونسبت لان احيانا يسون ترك وتسوي assumption غلط وتروح عليك.\nاذا حصل وقدرت سجل عند قطب مع انه ما يحتاج سلايدات الشرفي كافيه ووافيه", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203-thermodynamics-i/120732/35", "user": "Nasalmz", "ts": 1590430386000, "tid": 120732, "pn": 35}}', 1590430386000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1527203-me203', 'stk-abofordan2004', 'ME 203', 'info', '{"desc": "TERM 201 ONLINE\n\nمادة عادية كفهم ولكن اختباراتها وكويزاتها جدا جدا جدا صعبة طبعا الحمدلله ان المادة افرج ولا كان اغلبنا راسب فيها لان الاسألة فيها تحدي شديد للطالب بحكم انهم يلعبون بالقوانين والوحدات لعب\nبالنسبة للي فوق ويقول متعه وسهله و A+ بالجيب ما ادري هل هم يمزحون او صدق يتكلمون , الفاينل اللي جانا امس اسألته خرافيه وطويل الحل فيها والوقت ابدا مو كافي\nبغض النظر عن صعوبتها وطول الحل فيها الا ان المدرسين يحشرونك بالوقت واغلب الطلاب يسلم ورقته وهو ما كمل الحل\nاختصار الكلام ان المادة ذي زي الفيزيكس وممكن اصعب وفيها نفس شعور الاختبار لما تدخله وانت مذاكر فجاه تجيك اشياء اول مره تشوفها\n\nتوزيع الدرجات :-\n\nواجبات : 10%\nكويزات : 55%\nميدتيرم : 15%\nفاينل : 20%\n\nالميد تيرم هو الوحيد اللي كان سهل بس الباقي الله وكيلك , الحمدلله ان الكورس ذا خلص والله يستر من الثاني\n\nملاحظة : تقييمي لها بالاون لاين ( زمن كورونا ) ممكن تكون مختلفه جدا وربما افضل في الاترام العادية والله اعلم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203-thermodynamics-i/120732/38", "user": "AboFordan2004", "ts": 1608636115000, "tid": 120732, "pn": 38}}', 1608636115000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1531256-me203', 'stk-mohammed_alkalaf', 'ME 203', 'info', '{"desc": "Term 203\nالمادة ككونسبت سهلة جدا ومو طويلة لكن تحتاج تحل مسائل عشان تطلع بقريد كويس\nتقسيم الكورس كالآتي\nالكورس مكون من ٦ شباتر\nشابتر ١:\nمقدمة والمصطلحات الي تحتاجها … الشابتر مافي اي شي تقرا السلايدات كافي\nشابتر ٣ :\nشابتر ٣ قبل ٢ وهو عبارة عن جزئين الجزء الاول\nكيف تستخدم الجداول ( الجداول فكرتها مثلا لو عطاك ماء درجة حرارته كذا وعطاك اي شي ثاني ضغط او فوليوم او انرجي الخخ … يمديك تطلع باقي المعطيات من الجدول )\nالجزء الثاني هو عبارة عن الideal gases\nقانون الغاز المثالي وكيف تحدد هل هو غاز مثالي او لا واذا لا كيف تحسب خصائصه\n\nشابتر ٢:\nFirst law of thermodynamics:(\nconservation Of energy\nالشابتر هو عبارة عن حفظ الطاقة للنظام المغلق بمعنى السستم مايعبر خلاله شي او يطلع منه شي اثناء العملية\n\nشابتر ٤:\nنفس شابتر ٢ لكن السستم يكون مفتوح بتدرس فيه كم جهاز لهذي العمليات مثل الكمبرسور والturbine وغيرهم من التطبيقات\n\nشابتر ٥: second law of thermodynamics\nبتدرس اجهزة الثلاجة والمضخات والمكينة وكيف تحسب كفائتها\n\nشابتر ٦: الانتروبي\n\nالكورس تقريبا كله في ثلاث معادلات اساسية عشان تحل الاسئلة\nConservation of mass\nConservation of energy\nConservation of entropy\n\nكتاب المادة : بالنسبة لي ماقدرت اذاكر منه ولا عجبني\n\nمصادر المذاكرة : سلايدات الشرفي مهمة للكونسبت وتدرب على الاسئلة الي فيه واسئلة الهومورك مهمة وقبل الاختبار حل كم اولد", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203-thermodynamics-i/120732/39", "user": "mohammed_alkalaf", "ts": 1629045261000, "tid": 120732, "pn": 39}}', 1629045261000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p52386-me203', 'stk-rakan', 'ME 203', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\nمساء الخير جميعا , والله يوفقنا وياكم في هذا السمستر .\n\nاخواني انا اخذت مادة ME 203 لهذا السمستر الصيفي , مع الدكتور عمر القطب وهو دكتور جيد , وانا سمعت ان اختباراته ما يغير فيها كثير فالرجاء من اي - اخ كريم - اخذ المادة مع الدكتور القطب في اخر ثلاثة سمسترات مضت , ان يساعدني في الحصول على المياجر والكويزات وساكون له من الشاكرين .\n\nايضا طلب اضافي يا اخوان وارجو ما اكون ثقلت عليكم , انا محتاج لـSolution لمادة ME203 , فارجو منكم يا اخوان المساعدة بقدر المستطاع , والله مالي الا الله ثم انتوا .\n\nوهذا ايميلي لمن يساعدني مشكورا :\nal\\_faisal19@hotmail.com\nاو عن طريق الرسائل الخاصة , للتنسيق معه حول كيفية الوصول اليه.\n\nوالله يوفقنا وياكم في هذا السمستر لنيل ما نصبو اليه .\nولكم خالص التحية والتقدير .\n\nوالسلام عليكم ورحمة الله وبركاته", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me203/37110/1", "user": "RaKaN", "ts": 1089235581000, "tid": 37110, "pn": 1}}', 1089235581000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1461503-me203', 'stk-user9213', 'ME 203', 'info', '{"desc": "تفضل هذا نوت الدكتور قطب فيه شرح لكل شي بذا الكورس رفعه احد الطلاب من سنة ونص كذا , ذاكر اللي فيه و الجدول اللي فيه يشرح لك كيف توجد الخصائص من الجداول + الهومورك اللي يعطيه قطب طلابه و حاول تدبر السلوشن حقه من طلابه لأن الدكتور يحله بنفسه و تكون افكاره هي افكار الميجر بالضبط و اضمن لك تبدع فيها و تحبها . الكتاب لثيرمو 1 ممل نوعا ما بس اسئلتة ممتازة و اذا تبي تستزيد حل مسائل مشابه للهومورك من الكتاب و الله يوفقك .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me203/175202/3", "user": "user9213", "ts": 1477949951000, "tid": 175202, "pn": 3}}', 1477949951000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p47303-me203', 'stk-user514', 'ME 203', 'info', '{"desc": "انا اعرف دكتورين فقط…\n\nشاهين وتوماس\n\nبالنسبة لشاهين\nاول شي شرحه مررررررررررة سئ ونوته اسو ء يعني بالعربي اذا ماتضغط على نفسك وتذاكر اول باول ماراح تفهم شي لاكنه في بعض الاحيان يجيب اسئلة من النوت وتقريبا ميجر ون اذا صميت النوت راح تجيب قريد تمام لاكن بعد كذا راح يغير اسلوبه يعني تلاقي ميجر تو الافرج اقل لانه كل المسائل خارج النوت\n\nيعني من ميجر تو وفوق يعتمد عليك\n\nهو فيه شي متعب وهو الهوموركات كل اسبوع هوم ورك\nبس صراحة كلاسه من اكثر الكلاسات المملة الي مرت علي بالجامعة (يجيبلك النوم بالعربي)\n\nبس صراحة هو طيب ومتساعد بالمررة\nانا طلعت من عنده ب B مع اني كنت جايب في الميجر الاول والكويزالاول تحت الافرج\nاما توماس فالي سمعته عنه انه مياجره سهلة واذا كنت طالب متوسط تقدر تجيب عنده قريد\nاسئلة مياجره سهلة وكثير ة على عكس شاهين الميجر حقه اربع اسئلة بس\n\nيعني الافرج راح يتحكم فيك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me203/34470/2", "user": "user514", "ts": 1081866868000, "tid": 34470, "pn": 2}}', 1081866868000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1318292-me203', 'stk-abo_yazeed6', 'ME 203', 'info', '{"desc": "المادة بشكل عام تتكلم عن انتقال الحرارة ،والطاقة والشغل\nالأفرج فيها يعتمد على أفرج السكاشن تبع الدكتور على حد علمي.\nبالنسبة لي أشوفه كورس سهل وما هو صعب وأسئلته معقولة وعلى قد المنهج ،وكثير من الأسئلة تجي من أمثلة الكتاب والهومورك\nيمكن الشيء الوحيد الي قاهرني هو أول شابترين لأني أحس أنه ماله علاقة بباقي المنهج ،والدكتور أذكره ما كان مهتم كثير فيه.\nما أدري اذا كان له علاقة بالمواد المتقدمة لأني توني مخلص أول سمستر في السفمور", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203/155248/5", "user": "abo_yazeed6", "ts": 1389465608000, "tid": 155248, "pn": 5}}', 1389465608000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1324897-me203', 'stk-themagicstick', 'ME 203', 'info', '{"desc": "الكتاب الكتاب الكتاب ~~~ اذا انجليزيتك تمام\n\nاقرا على سريع و بفهم و اوقف عند كل مثال و حله كانه رح يجيك فالاكزام\n\nو بعد ما تخلص من التشابتر طوالي روح و حاول تحل اسئلة الهومورك بدون ما تشوف الحل و اذا عجزت خذلك hint من المانيوال سلوشن و كمل حل …\n\nو بس ،، على فكرة المادة سهله و يبغالك تحب المادة عشان تجيب فيها قريد\n\nو صلّ اللهم على محمد", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203/156183/4", "user": "TheMagicStick", "ts": 1391182169000, "tid": 156183, "pn": 4}}', 1391182169000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p76226-me203', 'stk-user467', 'ME 203', 'info', '{"desc": "وعليكم السلام ورحمة الله وبركاته\n\nاهلا بك اخوي فريشمان\n\nالصراحة قبل كل شي احب اقول لك انا اخذت المادة عند الدكتور مخيمر والصراحة لقيتها جدا ممتعة ومثل ماقال الاخ student ME المادة تعتمد على مذاكرتك بنسبة كبيرة وانتباهك في المحاضرة يختصر عليك وقت اثناء المذاكرة\n\nوبالنسبة لصعوبتها او سهولتها المادة ماتقدر تقول عنها صعبة ولا تقدر تقول عنها سهلة يعني مادة عادية وانا بالنسبة لي انصحك انك تذاكر من الكتاب اول بأول واي شي يصعب عليك انك تروح للدكتور على طول ولاتأخر اي شي لان هذي المادة تراكمية يعني اللي في المحاضرة الجاية دائما يعتمد على المحاضرة السابقة الى نهاية السمستر.\n\nاما بالنسبة لتنزيلها في الصيف عادي جدا وحتى لو تنزلها في السمستر العادي مافي اي مشكلة لان المادة مو ثقيلة.\n\nمع خالص تحياتي المستحيلية", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me203/47893/3", "user": "user467", "ts": 1116864163000, "tid": 47893, "pn": 3}}', 1116864163000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1162631-me203', 'stk-the_legend1', 'ME 203', 'info', '{"desc": "السلام عليكم\nانا طالب اخذتها الترم هذا (جبت b+ ) وكان يمديني على a\nالمادة سهلة\nفيه سلايدات للشرقاوي على الريسورس ادرس منها (الكونسبت)\nثم حل الاكزامبلز والهوموورك >> اضمن لك اقل شيء b+\nبعدها حل اسئلة مشابهة للهومورك\nوقت الميجر شف لك كم اولد اقزام\nوصل الله وبارك\n___\nللمعلومية\nانا صحيح ما جبت a بس لاسبابي الخاصة\nالمادة 3 مياجر وانا دخلت الميجر الاول ماني مذاكر بحكم ضغط الاختبارات\nوجبت تحت الافرج\n\nاما الميجر الثاني والثالث طبقت هذي الطريقة وضبطت معي\n\n___\n\nاتمنى لك التوفيق 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-a-me203/138224/2", "user": "THE_LEGEND1", "ts": 1357968771000, "tid": 138224, "pn": 2}}', 1357968771000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1163011-me203', 'stk-user5470', 'ME 203', 'info', '{"desc": "السرخي الافضل و الاحسن …\n-\nانا ما كنت اذاكر الا وقت المياجر و جبت قريد جيد موب a or a+\nبس سهلة فيها …\nانا كنت ادخل المياجر بدون لا اذاكر الهمورك بس يالله اخلص السلايدات\nطبعا سلايدات السرخي اذاكرها و اروح للميجر\nما كنت احل اولد اقزامس\n+\nراح ارفع الملفات المهمة اللي ساعدتني بس شوي خلي اروق ههههههههههه", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-a-me203/138224/5", "user": "user5470", "ts": 1358005932000, "tid": 138224, "pn": 5}}', 1358005932000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1043406-me203', 'stk-mr-3b0d', 'ME 203', 'info', '{"desc": "صراحة انا اشوف غلطتهم ترتيب الأسئلة\n\nأنا بديت واناظر السؤال الأول جبت الإليكتريك ورك ,وجبت السي في والسي بي لكن ما عرفت اجيب الباوندري ورك ولا عرفت ادخل الانثالبي بالسالفة( ولا مطلوب بالسؤال جبته)\n\nالسؤال الثاني قعدت اتفرج عليه 5 دقايق ثمن فتحت الصفحة\n\nبعدها انا كانت نفسيتي شبه منتهية لأن اول سؤالين ما حليتهم لكن الحمد لله السؤال الثالث والرابع معقولين جدا وقدرت أحلهم>>إذا كانت طريقتي صح\n\nالسؤال الخامس حليت الجزء الاول كامل والجزء الثاني كنت ناسي قوانين الايديل قاز فما عرفت احله\n\nيعني توقعي الآفرج يكون من 100: 50-55\n\nصراحة المادة كانت سهلة بس لو انهم يعطونا فورملا شيت كان يسهل علينا الموضوع كثيييييير\n\nبس يخافون ييعطونا فورملا شيتز والقريدات تصير بالسما", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me203/126128/27", "user": "mr-3b0d", "ts": 1337838105000, "tid": 126128, "pn": 27}}', 1337838105000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p78667-me203', 'stk-user60', 'ME 203', 'info', '{"desc": "أهلا بك أخي أنا سبقت واخذت الكورس هذا مع ابو الحمايل\n\nالمهم حلول الواجب تجدها متوفره مع طلاب الميكانيكال يعني اذا تعرف\n\nاحد من ال ام اي بيعطيك على شكل سي دي ((مع اني ما انصحك)) لان 70%\n\nمن الشغل حق الكورس يعتمد على حل الواجب صح بتلاقي صعوبه لكن في الاول و الاخير انت المستفيد\n\nبالنسبه للنوت فاعتقد ان لكل دكتور ستايل مختلف كليا فما انصحك اذا كنت تدرس مثلا مع شاهين تروح تاخذ نوت ابو الحمايل او الفرايضي او حتى باحيدره\n\nومن وجهة نظري الكتاب موضوح بشكل ممتاز ويكفيك في الشرح\n\nواذا رحت الجمعيه تسأل عن النوت ترا مو خطأ\n\nوخذ هذي على الطاير : نزل مع شاهين او الفرايضي وحاول بقدر الامكان تنزل معهم\n\nسي يووووو\n\nأخوكم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me203/48252/2", "user": "user60", "ts": 1123354157000, "tid": 48252, "pn": 2}}', 1123354157000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p75532-me203', 'stk-skfupm_a', 'ME 203', 'info', '{"desc": "وعليكم السلام ورحمة الله وبركاته\n\n1-اخي المادة تحتاج جهد وليس من السهولة فهمها لاحظ اقول ليس من السهولة مو معناتها انها ما تنفهم…\n\n2-حاليا الكتاب يكفي لان الاختبارات صارت كومون …\n\n3-بالنسبة لي(رأيي الشخصي) تنزلها باللفصل احسن لكن اذا\n\nلوحدها بالصيف… تمشي …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me203/47892/2", "user": "SKFUPM_A", "ts": 1115987336000, "tid": 47892, "pn": 2}}', 1115987336000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p75539-me203', 'stk-user905', 'ME 203', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\nأولا يا أخ فريشمان المادة متوسطة الصعوبة\nثانيا هي تعتمد بشكل كبير على المدرس واذا فهمتها راح تحب المادة مووووووووت\nنصيحتي أنك تحاول تهتم بحل عدد كبير من الاسئلة لأن المياجر common وتعتمد على فهمك للأسئلة. اهتم بالهوموركات وحوال تحلها بنفسك مع أنها صعبة حبتين. الفاينال بيكون مقارب للمياجر من ناحية الصعوبة.\nحاول تأخذها في سمستر عادي.\nأفضل المدرسين فيها بالترتيب:\nقطب\nسيد\nشاهين\nمخيمر\n\nواذا ما فهمت 203 راح يصعب عليك في 204\nبالتوفيق ان شاء الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me203/47892/3", "user": "user905", "ts": 1115993652000, "tid": 47892, "pn": 3}}', 1115993652000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p122224-me203', 'stk-user1346', 'ME 203', 'info', '{"desc": "لا يوجد سليوشن للنسخه الجديده من الكتاب الأسود\n\nولكن لما اخذتها من زمان كان عندي سليوشن ومتلخبط كثير لان النسخه تختلف ولكن راح يفيدك بالمذاكره وربما تجد اجوبه لأسئلة الهومورك ولكن بترتيب مختلف\n\nراح ابحث عنه وأرد لك خبر وللمعلوميه حجمه كبير جداً 90 ميقا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203/52608/3", "user": "user1346", "ts": 1160211278000, "tid": 52608, "pn": 3}}', 1160211278000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1378563-me203', 'stk-_0024', 'ME 203', 'info', '{"desc": "http://skfupm.kfupm.edu.sa/vb/showthread.php?t=47674\nموجود على هذا الرابط\n\nوبخصوصو مذاكرته حمل نوته السرخي\nواقرا منها بشكل اساسي واقرا الكتاب بشكل سريع\n\nالي ماتفهمه من النوتة ارجع للكتاب وافهمه الكتاب ممتاز بس في بعض الحشو\n\nثم حل الامثلة المحلولة الي بالكتاب كذا انت استوعبت الدرس\n\nبعدها حل اسئلة الشابتر الي تقدر عليه كل مازادت الاسئلة زاد فهمك وقريدك بخصوص الاولد اكزام المياجر تجي من الكتاب بالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203/162469/3", "user": "_0024", "ts": 1402270911000, "tid": 162469, "pn": 3}}', 1402270911000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p491990-me203', 'stk-storm', 'ME 203', 'info', '{"desc": "السلام عليكم\nكيف حالكم شباب\nكيف الاختبارات معاكم …يا عسى الله يوفقنا واياكم فيها\n\nاتمني يا شباب انكم تساعدوني من جد\nانا عندي اختبار ME203 مع الدكتور احمد شاهين يوم السبت القادم\nوالحمد لله مذاكر واسأل الله يوفقنا واياكم\n\nمشكلتي يا شباب …\nهي الـ (conversion ratio) وهي المعادلات اللي تخلينا نحول اليونتز\nوالله العظيم عقدتني وخلتني اشك في نفسي هل انا مذاكر صح وال مذاكرتي كلها غلط × غلط\nلأني اواجه صعوبه فيها لا يعلما الا الله …اتمنى من الشباب اللي عند الدكتور احمد شاهين\nيعطوني خبر … هل الدكتور طالب فيها او هل هي من متطلبات الكورس الا نكتفي بالـ SI units\nاللي هو النظام العالمي…\n\nانا اختباري يوم السبت المقبل 19 \\11\nارجوكم ارجوكم اتمنى تساعدوني\n\nووفقنا الله واياكم\nاخوكم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203/80067/1", "user": "storm", "ts": 1258053878000, "tid": 80067, "pn": 1}}', 1258053878000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p70145-me203', 'stk-wildthang', 'ME 203', 'info', '{"desc": "كاتب الرسالة الأصلية ابورمزي\n\nخذ عند القطب ولا تحتار\nالقطب ثم\nالقطب ثم\nالقطب\n\nهذا من وجهة نظري\n\nبكل صراحه قطب لا يعلى عليه انا اخذتها مع الدكتور عمرو قطب و تعرفون ان الماده يقولون انها صعبه و كثيفه و لكن دكتور قطب جعل الماده في قمة السهوله و اسلوبه جداً جميل و درجاته اكثر مما يستاهل الطالب و الرجل لا يعلى عليه", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me203/35835/6", "user": "wildthang", "ts": 1109488439000, "tid": 35835, "pn": 6}}', 1109488439000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1407707-me203', 'stk-user8715', 'ME 203', 'info', '{"desc": "وعليكم السلام ورحمه الله وبركاته\n\nيمديك بالراحة\nذاا كنت اتذكر صح ف شابتر 1+2 كلام غريب وما بيدخل في ميجر ون\nالمهم الحين عليك انك تفهم طريقة الجداول زين الي هو شابتر 3 +الكتاب ممكتاز جدا +نوتات السرخي بعد ممتازة\n\nاللي عليك انك تفهم من الكتاب او تحظر عند مدرس ثاني\nبعدين تحل كل الاكامبل المحلول وتكتب ملاحظاتك جنب الاسئلة\n+حل وافهم الهوم ورك + اولد اكزام\nوصل الله على نبينا محمد", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203/166590/6", "user": "user8715", "ts": 1414335610000, "tid": 166590, "pn": 6}}', 1414335610000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1408153-me203', 'stk-mec_engineer', 'ME 203', 'info', '{"desc": "انا اخدت الكورس وطلعت بيه بقريد الحلو الحمدلله\nكتاب المادة ممتااز جدا وهو افضل مكان تذاكر منه\n\nابدا بالاكزامبل حقت الكتاب حلها واقرا الدرس كويييس\n\nبعدين خش ع الاكسرسايز خذلك كم سؤال وامورك تزبط\n\nوترى الكورس مهم جدا لانه بتاخذ ثيرمو 2\nوبيعتمد عليه كثير", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203/166590/10", "user": "Mec_Engineer", "ts": 1414510488000, "tid": 166590, "pn": 10}}', 1414510488000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1034111-me203', 'stk-abu_hamad', 'ME 203', 'info', '{"desc": "انا اللحين اخذ الماده عنده وع كلامه يقول ان الماده ستاندر يعني الاي بلس 95 وماوفوق …بس والله حرام …حتى مواد الاسلامي صح انها ستاندر بس في اب قريد ومعظم المدرسين يسوون بونص لرفع الطلاب اما مع غاندي فما نقول الا الله يستر …بس المفروض كطلاب ان نحاول مع الدكتور يخليها افرج زي باقي السكاشن او يسوي بونص او اي شي …باعتقادي الاسئله للمياجر والفاينل تم وضعها ع اساس انها افرج فكيف يجي يسويها ستاندر…لازم والله نكلم الدكتور قبل لايخسف فينا .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203/125297/3", "user": "Abu_Hamad", "ts": 1336421160000, "tid": 125297, "pn": 3}}', 1336421160000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p979797-me203', 'stk-menoo', 'ME 203', 'info', '{"desc": "بالعكس … الـ 216 اسهل بمراحل من الـ 203 …\n\nالـ 216 مجال مسائله جداً محدود … اللهم الكونسبت هو اللي يلعب دور كبير ويخرب عليك …\n\nنظام المياجر 40% كونسبت … 60% مسائل …\n\nعشان تضمن الكونسبت … انصحك بالاولد اكزآمز والكتاب … الكتاب … الكتاب …\nالمسائل … شوف اسئله الهومورك وركز عليها وافهمها + الاولد اكزآمز + باقي اسئله الكتاب لو كنت تبي الـ +a\n\nطبعاً الـ 216 بشكل عام ماده حلوه ماهي صعبه … اصعب الشباتر يمكن 6 & 9 فقط …\n\n---------------------------\nالـ 203 … انا ذاكرتها من سلايدات السرخي + اسئله الهومورك + بعض من اسئله الكتاب بافكار مختلفه …\n\nوما اظن فيه احسن من طريقه انك تفهم الاكزآمبلز + تمسك اسئله نهايه كل شابتر وتحل وتحل لين تمل …\n\nطبعاً بالنسبه للي ماسكين الـ 203 من الدكاتره … يفكرون بشكل غبي بوضع الاسئله لكن لا تخاف …\n\nذاكر تنجح … :]", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-216-me203/119765/6", "user": "Menoo", "ts": 1328379559000, "tid": 119765, "pn": 6}}', 1328379559000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p709713-me203', 'stk-dark-future', 'ME 203', 'info', '{"desc": "أول شي أبشرك الدكتور حبيب\nشرح طريقه الكورس وعطانا الـSyllbus حق الماده\nبدا في الماده وشرح\nوعطا التوزيع للماده كالتالي :\nميجر 1 20%\nميجر 2 20%\nكلاس تست 10 %\nهوم وركات 10%\nفاينل 30 %\nطبعا الكلاس تست في 1 نوفمبر\nوالميجر 1 في 5 ديسمبر\nوالميجر 2 في 3 jan\n\nاول ما تجي اسأله عن السلبس فيه كل شي\nوفالك الـ A+\n\n🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203-gandhidasan/95517/3", "user": "DaRk-FuTuRe", "ts": 1285693688000, "tid": 95517, "pn": 3}}', 1285693688000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p968798-me203', 'stk-user5891', 'ME 203', 'info', '{"desc": "الله يستر\n\nوالله مع إحترامي لهالدكتور لكن بعض الأحيان احس انه نفسية من الدرجة الأولى\n\nاتذكر قيل ميجر 2 رحت له الأوفس وعندي كم استفسار في بعض الأختبارات القديمة لكنه احرجني وقال لي اكانت\n\nيعني قصده جيب لي سؤال من الكتاب واشرحه لك اما تجيب لي اولد اقزام انا ماراح اشرج لك ولا شي سألنه طيب وش الفرق قال هذي الأولد اقزام مو انا اللي كاتبها لذلك ما عندي اي خلفية عنها ويمكن تكون من خارج الكتاب فما ابغا اشرح لك شي وبعدين يطلع غلط >>>>شوف العذر اللي اقبح من ذنب\n\nيعني إذا انت وكتور صار لك فوق ال20 سنة تدرّس هالمادة يمكن تخطئ في سؤال من خارج المنهج واما احنا الطلاب اللي تونا ناخذ الكورس تبغونا نحلهم دايركتلي\n\nوفي النهاية قلت له انا فاهم السؤال حليته من قبل لكن ابغا اعرف وش الفرق بين هالنقطة وذيك النقطة وانا اذكر اني حليت سؤال مشابه له في الأولد إقزام\n\nقال لي نورماللي آي دونت سولف اولد إقزامز قلت له طيب اجل انا استأذن لأن كل اسئلتي من الأولد إقزام >>> وخلاني امشي بدون ان يجاوب على سؤال من اسألتي\n\nالله يستر بس", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me203/118271/8", "user": "user5891", "ts": 1326702525000, "tid": 118271, "pn": 8}}', 1326702525000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1444960-me203', 'stk-user10542', 'ME 203', 'info', '{"desc": "شوف احمد شاهين شرحة حلو ويمشي بالتصحيح لاكن طريقة الشرح تجيييب النوووووووم ،مرة تجيب النوم وبنفس النبرة والنبرة واطية جدا\nالحلو فيه ان لمن تروح له للميجر او الكويز وتقول له تاكد من تصحيحك ، يرجعها لك بزيادة +١ (جربتها كل المياجر والكويزات)\nلاكن\nالقريد ستاندر عنده يعني ٩٥ a+ لاكن قطب 80 a+ شوف الفرق العظيم يعني واحد ياخذ b+ وواحد ياخذ a+\nطبعا ع ماسمعت ان قطب يهتم فقط لل قوانين يعني لو تكتب القانون صح والتعويض خرابيط ممكن يعطيك نص الدرجة وممكن اكثر .\nنصيحتي خذ قطب وفالك a+", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me203/172665/12", "user": "user10542", "ts": 1458999980000, "tid": 172665, "pn": 12}}', 1458999980000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p567709-me203', 'stk-user4130', 'ME 203', 'info', '{"desc": "خذ العلم مني وانا اخوك المادة مو صعبة ذاكر من السلايدات طبعا الاشياء المهمة فقط لان فيه اشياء مذاكرتها مضيعة وقت لانك راح تفهمها وتعرف اذا حليت الامثلة والمسائل\n\nحل مسائل الهومووركز راحت تفيدك جدا لان هذي كانت طريقتي لمذاكرة المياجر و حصلت درجات ما كنت اخلم فيها\nلكن الفاينل ذاكرت له من الفاينلات القديمة وحصلت درجة سيئة\n\nاخيرا : اول سمستر عملوا فيه الكومن ميجر هو السمستر الماضي وانا مازلت احتفظ بالمياجر اذا كنت تبيها ممكن اصورها لك عشان تستفيد منها مستقبلا في المياجر لانها ما راح تفيدك ب(الكلاس تست)", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me203/85509/3", "user": "user4130", "ts": 1268778196000, "tid": 85509, "pn": 3}}', 1268778196000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p288137-me203', 'stk-msasb', 'ME 203', 'info', '{"desc": "السلام عليكم\n\nكيف حالك يا طلاب الكيميكال 🙂\n\nاليوم بعد البحث وجدت سلوشن للمادة اللي تدرسوه ونسخة جديدة 5 edition\n\nوقريباً جاري البحث عن باقي الكتب في مختلف التخصصات بس أبي منكم تعاون وهو ، كل واحد يكتب لي الكورس واسم مؤالف الكتاب ونحوه ، وأنا سأجلب السلوشن وجميع ما يتعلق في هالمادة\n\nلا أطيل عليكم هذا هو روابد التنزيل واتمنى منكم الدعاء\n\nوبالتوفيق يا أخواني 👍\n\nروابط رابيدشير\nhttp://rapidshare.com/files/131600504/_Solutions_Manual__Thermodynamics_-_An_Engineering_Approach__5Th_Cengal_Boles.rar\n\nhttp://rapidshare.com/files/131600507/_Solutions_Manual__Thermodynamics_-_An_Engineering_Approach__5Th_Cengal_Boles_2.rar\n\nوجاري رفعها إلى موقع ميديا فاير", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me203/64755/1", "user": "Msasb", "ts": 1216741022000, "tid": 64755, "pn": 1}}', 1216741022000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1319029-me203', 'stk-abu-rasheed', 'ME 203', 'info', '{"desc": "و الله شوف أخي العزيز ، المادة تتكلم بشكل عام عن energy equation ، وايضا تتكلم عن system and control volume ، وايضا تتكلم عن carnot efficiency and refrigeration cycle and tables. طبعا فيه قانون راح تستخدمه على طول عشان تحل أي مسألة تتعلق بالنظام اللي هي energy equation. هذا بالنسبة لمحتويات المنهج أما بالنسبة لتقسينة الدرجات فهي عادة تكون آفرج سكشن أو ستاندرد في بعض الأحيان على حسب الدكتور اللي تاخذ معاه هذا الكورس الجميل.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203/155248/11", "user": "ABU-RASHEED", "ts": 1389689851000, "tid": 155248, "pn": 11}}', 1389689851000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p85190-me203', 'stk-user165', 'ME 203', 'info', '{"desc": "لخبطوا الرجل\n\nانا درست عند مخيمر دكتور محترم خلوق جدا …\n\nمياجره متوسطه قريداته فوق المتوسطه … يعني على قد اجتهادك تاخذ.\n\nاما الفرائضي فللأمانه كنت اتمنى ان تتاح لي الفرصه حتى استفيد من علمه … لم اجد شخص درس عنده الا و دعا له بالخير …\n\nيعني الجميع ممتازين جدا وهم من افضل دكاترة القسم\n\nالترتيب ::: فرائضي\nمخيمر\nشجاع -> اختباراته صعبه لكنه يفهمك الماده وراح تستفيد في الكورسات اللاحقه ان شاء الله .\n\nوموفق ان شاء الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me203/49101/5", "user": "user165", "ts": 1133624115000, "tid": 49101, "pn": 5}}', 1133624115000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1429655-me203', 'stk-othmann', 'ME 203', 'info', '{"desc": "الكويز بكرة ومتيريل الهوموورك الثاني الي هو سؤال ظ¢ظ£،ظ¢ظ¦،ظ£ظ£،ظ£ظ§،ظ¦ظ* من تشابتر ظ£ الي اعطانا اياها بالكلاس ولا ندري عن درجة الكويز بس اذا بتجي بكرة ذاكر …الهومووركات يعطينا اياها بالكلاس والميجر بظ¤ نوفمبر… ولا فاتك شيء ان شاء الله\n\nDropbox - ME203.pdf\nهذي النوتات الي يكتبها بالكلاس ذاكر منها بعدين شوف الهوموورك … ممتازة مرة والله يوفقك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me203/170244/2", "user": "othmann", "ts": 1444038011000, "tid": 170244, "pn": 2}}', 1444038011000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p979958-me203', 'stk-turky_al-dossary', 'ME 203', 'info', '{"desc": "216 الكتاب وبس ،، نصيحة انا جربت الفرق\n\nذاكرت المياجر من كل السلايدات :: ظفر الله وخان وغيره وما ادري وش الطبخة ،، واتوقع كل واحد بيقول الي ذاكر منها مو الافضل ،، وانا اوفر عليك الوقت عشان ما تضيعه في السلايدات بس مر على سلايدات مدرسك عشان تشوف وين مركز في الكويزات 🙂\n\nاما الفاينل ذاكرت من الكتاب فهمت المادة ،، بس اهم شيء اول باول لانه طويل\n\nوفي شرح بالعربي للمادة في اليوتيوت يشرح من نفس كتابنا ،، اتوقع في موضوع في المنتدى كان موجو الرابط فيه", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-216-me203/119765/7", "user": "Turky_Al-Dossary", "ts": 1328389318000, "tid": 119765, "pn": 7}}', 1328389318000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p984719-me203', 'stk-a7madd', 'ME 203', 'info', '{"desc": "في الـ216 مالك غنى عن الكتاب… والأولد إقزامز تسوى ذهب في الكورس هذا بالذات !! لأن الأسئة دايم تتكرر.\n\nفي الـ203 لازم تعرف تحل المسائل. تحصل على المهارة هذي بأي طريقة تفضلها. سواءً بقراءة الكتاب وفهم الكونسبتس أو بحل الإكزامبلز اللي في الكتاب أو بحل الهومورك بنفسك أو بالتركيز على شرح الدكتور وغيرها.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-216-me203/119765/10", "user": "A7madd", "ts": 1329064523000, "tid": 119765, "pn": 10}}', 1329064523000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p100500-me203', 'stk-user505', 'ME 203', 'info', '{"desc": "وعليكم السلام ورحمة الله وبركاته :\nبالنسبة لل me203 ، المادة بالنسبة لي كانت من النوع السهل الممتنع ، يعني أهم شي إنك ماتخلي المادة تتراكم عليك وتحاول إنك تتابع المادة أول بأول. راح تدرس نفس الجزء اللي درسته في (فيزكس 102 ) المتعلق ب ال Thermodynamics ولكن بشكل أوسع ، مثل ال work,effieciency,entropy>>>\n\nبالنسبة للاختبارات،كل مدرس يحط الأسئلة الخاصة فيه ، ماعدا ال(ميدتيرم) فيكون موحد لجميع الطلاب والفاينل يكون موحد مع سؤال أو سؤالين يحطهم المدرس اللي تدرس عنده.\n\nبشكل عام ، المادة بسيطة إن شاء الله وماهي من النوع اللي تشيل همها.\n\nوإذا عندك أي استفسار,أنا والإخوان موجودين.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me203/50849/2", "user": "user505", "ts": 1149899488000, "tid": 50849, "pn": 2}}', 1149899488000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p922811-me203', 'stk-user5712', 'ME 203', 'info', '{"desc": "غريبة من الأعضاء التأخر في الرد ، خصوصاً قسمنا أنا أشوف أنه نشط\n\nبالنسبة للثيرمو :\nأنا أشوف أن المادة سهلة حيل ، بس الكتاب طويل وفي بعض السكاشن معقدة فيتجاهلها المدرسين ولا تدخل معنا\nعلشان كذا أنا أذاكر من سلايدات مدرسنا وفي نفس الوقت أشيك على الكتاب على السريع وأشوف إذا فيه معلومة زايدة أمر عليها\nبعد ما أخلص مذاكرة السلايدات ، أحل مسائل من الكتاب وخصوصاً مسائل الهومورك تأكد أنك تعرفها مضبوط\n\nوإذا قرب الميجر (هذي القاعدة حاول تسويها مع كل المواد) لازم تحل مياجر قديمة ، حتى لو واحد على الأقل\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me203/114119/4", "user": "user5712", "ts": 1319140424000, "tid": 114119, "pn": 4}}', 1319140424000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p934041-me203', 'stk-user4626', 'ME 203', 'info', '{"desc": "مقارنة بالمياجر القديمة فهو جدا صعب\nأنا آشوف فيه صعوبة نوعا ما ما عدا يمكن السؤال الاول فقرةb و الاخير الصح و الخطأ و الاختيار كان نوعا ما سهل\nالسؤال الثالث حق التورباين متوسط\nالسؤال الرابع فيه صعوبة لان الي كتب السؤال ما يعرف يعبر و السؤال الاول فيه شوية حوسة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me203/115227/2", "user": "user4626", "ts": 1321815195000, "tid": 115227, "pn": 2}}', 1321815195000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p742903-me203', 'stk-mesho', 'ME 203', 'info', '{"desc": "وائل أحمد…\nياجماعة هالدكتور من الطراز الفاخر…\nمحترف بالمادة ,\nبطلللللل\nمن جميع النواحي …,\nكوزاته سهلة مرةةةةةةةة … يعني لازم تجيب فل مارك(س)\nالشرح بطللللللللللللل … مايخليك تطلع من الكلاس الا وانت فاهم …\nوالتصحيح … ممتاز\nمتفاهم من ناحية الهوموركات … << يعني تقدر تأجل تسليم هووم وررك مرتين في الترم زي العسل\nتقييمي له ++++a\nسجل عنده وانت مغمض…\n( وماخاب من أستشار )\nبالنسبة للاخريين مادري عنهم …,\nالله يوفقكم …,", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me203/98953/8", "user": "MESHO", "ts": 1292190189000, "tid": 98953, "pn": 8}}', 1292190189000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p793816-me203', 'stk-break', 'ME 203', 'info', '{"desc": "بما ان كتاب الماده يذكرني بكتاب الفزكس من ناحيه التعقيد فلابد من السلايدات السهله اللي تبسط الماده ما تعقدها اتمنى منكم ارشادي الى السلايدات الشامله والكامله التي تقودني نحو الاي بلس بعد توفيق الله واذا امكن وضعها هنا اكون شاكر ومقدر لكم حسن تعاونكم .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203/103224/1", "user": "Break", "ts": 1298031571000, "tid": 103224, "pn": 1}}', 1298031571000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p797609-me203', 'stk-abdullah_al_shammari', 'ME 203', 'info', '{"desc": "يا الرئيس الكتاب كلامه واجد وطويل … بمعنى أنه ما يركز على الزبده الموضوع << الى درجه أنه يطلع من موضوع الدرس ويتكلم عن أشياء ثانيه\n\nمثل ما قال أخ بريك ما يذكرني الا بكتاب الفيزيكس << اللي ايامها ما عمري فتحته وكنت أذاكر من السلايدات\n\nوعسا الله يساعدنا 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203/103224/9", "user": "Abdullah_Al_Shammari", "ts": 1298388804000, "tid": 103224, "pn": 9}}', 1298388804000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p722590-me203', 'stk-user4636', 'ME 203', 'info', '{"desc": "^^^^^^^^^^\nهذي هي انا نفس الشي اهم شي المعدل\n\nبس ودي اعرف هل فعلا اسئلته صعبه و “استقعادي” بالدرجات ولا نظامه بس تخويف عشان نذاكر ومدري ايش؟؟\n\nاذا هو فعلا تعقيد اسئلته خاصه ان بيده 25% عالاختبارات غير الواجبات هذا شي صعب صراحه وقهر اني اشد حيلي واجيب مثلا 18 من 25 وناس عند مدرسين ثانين تجيهم اسئله سهله ويجيبون نفس الدرجه او اعلى 😦\n\nفا مدري اذا هو شديد حتى بالاسئلة والقريدز ويستقعد على كل خطأ واذا مثلا اخطيت بحاجه بسيطه يعطيك خطأ على السؤال كله\n\nهذي المشكله وراح احذفها دايركت لو هو كذا بدون اي تفكير حتى 🙂\n\nبكيفها اجلس هالترم 12 ساعه واخذها الترم الثاني او الصيف مافي مشاكل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me203/96843/5", "user": "user4636", "ts": 1287269434000, "tid": 96843, "pn": 5}}', 1287269434000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p727895-me203', 'stk-kfupmss', 'ME 203', 'info', '{"desc": "if u want to increase ur gpa solve more than homeworks questions\n\nif u want to reach ur avg gpa solveonly thehomework questions\n\nif u dont want to work ur gpa will decrease\n\nكل كلاااااااااس ازعجنا ماغير يقولنا ذي المقوله\n\nمحد قالـــه ان المادة 3 ساعات موووب 60 ساعة\n\nطيب حلينا اسئلة الهومورك وحلينا فوقها اسأله وفي الاخير افرج الكويز الاول 2.8 من 10\n\nيعني جايب سؤال في الكويز عليه 60% من درجة الكويز ومافي ولا واحد جاوبه عندهـ غير طالب واحد\n\nويقول التيست اصعب منه بعد\n\nمدرس يرفع الضغط صراحا (superheated vapor )\n\nبس ماني مدردبها\n\nبخليها واخلص منها\nيعني لاتتوقع طول حياتك الجامعية مارح تواجه صعوبات مع الدكاترة او المادة\n\nوبعديــن تراها 3 ساعاااات مهي 20 ساعة\n\nيعني ضبط نفسك في المواد الثانيه والافرج راح يرتفع حتى لو خبصت في ذي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me203/96843/9", "user": "KFUPMss", "ts": 1288170219000, "tid": 96843, "pn": 9}}', 1288170219000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p478568-me203', 'stk-_a13', 'ME 203', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nالسلام عليكم ورحمة الله وبركاته\n\nمساء\\صباح الخير\n\nإخواني أردت المساعدة منكم في كيفية مذاكرة مادة الـme 203\nلأني أنا منزلها مع الدكتور (الشعراوي) وماعنده سلايدات زينة والكتاب مثل ما انتوا عارفين متشعب ويتوه\nأنا حصلت على مانول سليوشن لكن أردت الحصول أيضاً على شيء يساعد (سلايدات ، نوت ، …)\nوأنا سمعت أن الدكاترة الباقين عندهم سلايدات ممتازة\nفإذا كان أحد الأخوان عنده هالسلايدات ياليت يساعدنا فيها ونكون له من الشاكرين\nوالله يجعلها في موازين حسناتكم\n\nشكراً\n\nأخوكم \\ الشامخ", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203/79118/1", "user": "_A13", "ts": 1255964196000, "tid": 79118, "pn": 1}}', 1255964196000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p479127-me203', 'stk-user2552', 'ME 203', 'info', '{"desc": "مثل ما ذكر اخوي … قحطاني\n\nحاول تقرأ الكتاب … و تحل الأمثلة\n\nانا عارف ان الكتاب يسبب ازمة عند طلاب كثير … لكن\n\nصدقني لو تعودت عليه … راح تبدع في الاختبارات\n\nشي ثاني … الهومورك … لا تنقله من السيليوشن\n\n(( نصيحة : حله بنفسك … على حسب فهمك و مذاكرتك ))\n\nبعدين تأكد من حلك … باستخدام السيليوشن\n\n(( ذاكر اول باول … و لا تراكم المعلومات عليك ))\n\nانا للاسف ما عندي … نوت او سلايدات للـ me 203\n\nاتمنى لك كل التوفيق 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203/79118/4", "user": "user2552", "ts": 1256052188000, "tid": 79118, "pn": 4}}', 1256052188000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p480525-me203', 'stk-user3489', 'ME 203', 'info', '{"desc": "والله مثلك المادة ذي مدري وش تبي - الى الحين- ؟؟؟\n\nأنا عندي سلايدات بس مدري إذا اللي تقصدها انت ولا غيرها…\n\nبحاول أنزلها هنا …\n\nبس للشباب اللي أخذوا الكورس قبل…\n\nهل فيه أولد إكزامز ؟؟ كيف طريقة مياجرهم؟؟ نفس أسئلة الكتاب؟؟\n\nلأن صراحة أسئلة الهوموورك صعبة جدا …\n\nوالكارثة إن دكتورنا إلى الحين من بداية السمستر ما حل ولا مسألة …\n\nبمعنى الكلمة … ولا مسألة …\n\nوالهورم وورك كله مسائل ومعقدة…\n\nالله يعين …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203/79118/8", "user": "user3489", "ts": 1256303969000, "tid": 79118, "pn": 8}}', 1256303969000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1429557-me203', 'stk-noni_xd', 'ME 203', 'info', '{"desc": "وعليكم السلام ورحمة الله وبركاته …\n\nالكويز الأول كان عن تشابتر 1 + 2 = جاب الأسئلة من تشابتر 2 لان تشابتر 1 تحويل وحدات …\n\nالكويز الثاني يقول انه من تشابتر 2+ 3 = اتوقع يجيب السؤال من تشابتر 3 لان تشابتر 2 اخذنا فيه كويز …\n\nذاكر اي شي … أهم شي إنك تكون فاهم …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me203/170226/2", "user": "noni_XD", "ts": 1443910568000, "tid": 170226, "pn": 2}}', 1443910568000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1429563-me203', 'stk-user8890', 'ME 203', 'info', '{"desc": "وعليكم السلام\n\nWhat Are Pure Substances?\nhttps://www.youtube.com/watch?v=Ze0kG4yeFS0\n\nthen watch\nThermodynamic Properties Part 1\nhttps://www.youtube.com/watch?v=r7bfafHg8uY\n\nThermodynamic Properties Part 2: very very very important.\nhttps://www.youtube.com/watch?v=ZxFO3AIRIu8\n\nThermodynamic Properties Part 3 - Property Tables\nhttps://www.youtube.com/watch?v=3btbPs5wvNw\n\nالمادة سهلة صدقني, الميجر الأول سهل وتبي تتمكن منه اذا عرفت استخدام الجداول وهذي المقاطع بتفيدك إن شاءالله .\n\nموفق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me203/170226/3", "user": "user8890", "ts": 1443921451000, "tid": 170226, "pn": 3}}', 1443921451000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p892289-me203', 'stk-a_hme_d', 'ME 203', 'info', '{"desc": "ابقولك تجريبتي في الصيف الي راح وراح تفيدك ان شاء الله :\n1- اقرا الكتاب على السريع واكتب القوانين في ورقة خارجية .\n2- حل امثلة الكتاب المحلولة .\n3- حل الهومورك بنفسك ومافيه مانع تشيك على السوليوشن عشان تتاكد من حلك لكن في البداية حاول تحله بنفسك .\n4- اسئلة المياجر والفاينلز نفس افكار اسئلة الهومورك يعني ركز على اسئلة نهاية كل شابتر وسيبك من الاولد اقزام .\n\nلو سويت هذي الاشياء ان شاء الله اقل شي يمكن تاخذه b+ ( هذا اقل شي اذا كان الافرج مرتفع )\nبالتوفيق.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me203/111260/6", "user": "a_hme_d", "ts": 1314389952000, "tid": 111260, "pn": 6}}', 1314389952000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p894129-me203', 'stk-_hlali', 'ME 203', 'info', '{"desc": "++++1\n\nهو الكورس صراحه يبدأ من شابتر 3 الي هو الجداول يعني اذا فهمت\n\nشابتر 3 مظبووووط يعني تعرف كيف تستخرج من الجدول المطلوب فاعرف ان\n\nوضعك في السليم لان الشباتر الاربعه الباقي تعتمد على هالجداول\n\nومثل ماقال اخوي حاول تركز على الكلاس وورك لانه 20 بالميه من الكورس\n\nوقبل المياجر اغلب الدكاتره يسوون مراجعه للميجر في بعضهم يحل افكار\n\nممكن تجيك قريبه منها او نفسها يمكن فيعني قبل الميجر شوف ربعك\n\nالي في السكاشن الثانيه وجمعوا الافكار كلها وان شاء الله الاختبار مايطلع منها .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me203/111260/14", "user": "_HLALI", "ts": 1314966175000, "tid": 111260, "pn": 14}}', 1314966175000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p894982-me203', 'stk-user1333', 'ME 203', 'info', '{"desc": "اول شي حبيت انوه لطلاب الميكانيكال بالذات الفريشمان ان مواد الميكانيكال اسهل من مادتي الفيزيكس 101-102 (وجهة نظر خريج) …\n\nme 203 من امتع المواد اللي درستها هي و me 311… اذا فهمتها راح تحبها وهي سهلة ماهي صعبة … التشابتر الاول والثاني مافيها صعوبة بالعكس سهلة … من التشابتر الثالث وحتى الاخير السابع كلها تعتمد على الجداول … حاول انك تفهم تشابتر 3 زين وتحل فيه اكثر عدد من الاسئلة لأنك اذا فهمت الجداول وطريقة استخدامها راح ترتاح بالمادة كثييييير … وزي ماقلت لك المادة حلوة وممتعة بنفس الوقت اذا فهمتها … والله يوفقك لل A+", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me203/111260/15", "user": "user1333", "ts": 1315212969000, "tid": 111260, "pn": 15}}', 1315212969000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p513992-me203', 'stk-e_khaloodi', 'ME 203', 'info', '{"desc": "مو شرط تضغط نفسك وتبدر بالكمستري … انت الترم الجاي خذ اي سي اس … وفي الصيف ممكن تاخذ لك ماث ٢٠١ وme 203 مثلا … …دوامك ساعتين في الصيف وما راح يكون عندك ضغط لابات وبتحصل وقت تشد حيلك فيه ان شالله … في المقابل اول ترم في السفمور نزل كمستري … وبكذا تكون ضربت اكثر من عصفور بحجر … الترم الجاي موادك مافيه ذاك الضغط + الصيف ما عندك ضغط لابات\n\nاذا كنت بتنزل الكمستري الترم الجاي وشايف انك ممكن تتحمل ماث وفزكس وكمستري وانجلش هذا احسن شي ممكن تسويه ( لو بتشد حيلك وبتتحملهم )\nلكن انصحك تنزل يوم رستيشن الفزكس مختلف عن الكمستري ( عشان ما تبلش كل اسبوع كويزين كمستري وفزكس بنفس اليوم )\n\nبالنسبه عن صعوبه الاي سي اس … الماده سهله لكن يبيلها فهم اول بأول … اللاب فيها برضو مهم انك تسويه بنفسك … صدقني لما تفهمها اول بأول بتصير سهله وبتطلع بقريد عالي ان شالله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/81574/13", "user": "E_khaloodi", "ts": 1262388497000, "tid": 81574, "pn": 13}}', 1262388497000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p613307-me203', 'stk-al-harbi', 'ME 203', 'info', '{"desc": "السلام عليكم\nكييفك الشباااب هاااااا عساكم بديتوا مذاكره للفاينلااات\n\nعلى العموم شباب\n\nمن فين أحصل على اوولد إقزام للمجير 2 ME203…\n\nالشي الثاني\n\nكيف ماده numerical methods سهله صعبه تتكلم عن إيه يعني من الأخر سهالات إذا أخذتها في الصيف…\n\nو كالعااده ما لقيت ولا سكشن فاتح لها في الصيف …كيف أسوي أبروفل ومتـــى\n\nو رحــــــــــــم الله ولديكم… 👍", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/88692/1", "user": "AL-HARBI", "ts": 1274579341000, "tid": 88692, "pn": 1}}', 1274579341000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p404206-me203', 'stk-user2352', 'ME 203', 'info', '{"desc": "نعم أنت مخير في اختيار أي كورس 3 ساعات حتى ولو كان انجنيرنق ولكن أنصحك لا تستعجل في دراستها لأنه من المعروف إن الطالب يدرس كورس إلكتف علشان يرفع معدله ،، إلا إذا شفت إن لديك الرغبة في الدراسة الصيفية وتميل للفزكس فعندك me 203 خصوصا إذا نزلها الدكتور الفرائيضي أعرف واحد حول من ميكانيك لأندستريال وعادلوها له فري إلكتف ،،،\nوبالتوفيق،،،", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/free-elective/73374/5", "user": "user2352", "ts": 1242679975000, "tid": 73374, "pn": 5}}', 1242679975000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p114141-me203', 'stk-saddah', 'ME 203', 'info', '{"desc": "وعليكم السلام\n\nوعلى البركة انتقالك وبالتوفيق\n\nبالنسبة للـ Me203\nاللي أعرفه ومجربه\nمحمد حبيب : مايعرف يشرح ومتعاون كثير في الدرجات وقريداته غير متوقعه يعني اذا توقعت B يعطيك A وهو أفضل مدرس اذا كنت تستطيع أن تمسك الكتاب لوحدك وتفهم من دونه.\nقطب: يقولون شرييييح ومتساهل وافرجه عالي وقريدك يتأثر سلباً بالارتفاع هذا\nالفرائضي: يمدحونه مياجره متوسطه واذا دفرت عنده تطلع بـ A+\nعنتر : سمعت عنه بس مدري يمدحونه أو يذمونه ممكن يفيدونك شباب المنتدى\n\nبالنسبة 210\nمادرست عند واحد فيهم بس روميتي أخذ عند أوبراين وطلع بـ A\nآراء الطلاب تتفاوت فيه اللي يسب واللي يمدح\n\nبالنسبة215\nنزل عند ظفرالله خان دايركت، قريداته حلوة ومياجر متوسطة لكن يغثك في الاختيارات يبيلك تكوزن مذاكر بتمعععععععن وهو بشكل عام ممتاز\n\nاللاب : يمدحون رضا\n\nوبالتوفيق مرة ثانية\nوالسلام عليكم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/51933/2", "user": "Saddah", "ts": 1157153971000, "tid": 51933, "pn": 2}}', 1157153971000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p721246-me203', 'stk-user3994', 'ME 203', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاااته…\n\nاخبار الشبااب والميكانيكيين يالبى قلبكم ❤️ 🌹<< يتمصلح 😆\n\nاحبكم كل ابووكم << برضو يتتمصلح\n\nاقول الحين وشلوون نذاكر مادة ME203 كتابهاا غثيث وكبير ومالها سيلبولس يورييك ان كان فيه سكاشن محذوفة ولا لا لان بعض السكاشن مايتكلم عنهاا الدكتور واحيان يتطرق لها بسرعة\nوبيني وبينكم الدكتور حقناا ذا مرة مايطمن الشرح في جهة والكويز في جهة اخرى يبغاله 🥊 🥊\n\nفيا اعزائي الميكانيكين اذا تعرفون لي سيلبولس او طريقة او ملخص او اي شي اذاكر بهاا ذي المادة الجميله << 🤓\nاكون لله شاكرا ثم لكم\nسي ييوووو", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/96719/1", "user": "user3994", "ts": 1287055480000, "tid": 96719, "pn": 1}}', 1287055480000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1085461-me203', 'stk-user5689', 'ME 203', 'info', '{"desc": "205 المادة متوسطه وآفرجها عالي … الكتاب ممتاز\n\n203 الماده متوسطه والمنهج طويل جدا ويحتاج وقت لتغطي الماده … الكتاب ممتاز\n\n207 الماده بوجهة نظري أصعب مواد ليفل 2 + كتابها سيئ جدا … آفرج الماده عادة يكون نازل كثير\n\nme203 الماده تراكميه وتعتمد على فهمك للجداول ( في الاسبوع الثالث ) + الكتاب جيد\nبشكل عام الماده متوسطه .\n\nتحتاج شدة حيل … وانتبه عن التسويف\nفالك النجاح والتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/130913/4", "user": "user5689", "ts": 1346588385000, "tid": 130913, "pn": 4}}', 1346588385000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p202782-me203', 'stk-user1419', 'ME 203', 'info', '{"desc": "الدكتور مخيمر:\n\nأخذت معه ال me203 قبل 3 سنوات .\n\nالرجل فاهم لكن توصليه للمعلومة مو مرة .\n\nاختباراته متوسطة .\n\nقريداته متوسطة كذلك.\n\nعلى دفعتي كان في الفصل 5 طلاب فوق التسعين من ميه في الكورس و واحد بس أخذ A+\n\nيعني الدكتور مو النوع الي يحب يعطي قرايدات عالية أو قريدات منحفظة.\n\nشــــــــــــد حليك الكورس مهم للكورسات الثانية.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/58597/4", "user": "user1419", "ts": 1189673385000, "tid": 58597, "pn": 4}}', 1189673385000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p747550-me203', 'stk-korabeka', 'ME 203', 'info', '{"desc": "إذا بديت تخاف من الضغط الحين , أجل وش بتسوي في لفل 3 و4\n\nما أقول الكلام ذا تخويف بس خلاص إذا بديت في التخصص أعرف أنك بتكون في ضغط إلى آخر الترم\nوبالنسبــة لنصيحتي لك فأنصحك من قلب محب أنك تنزل ME203 في الصيف\nو phys203 قبل se301\n\nبتقولي ليش …\nأولا زي ما قلت المــادة صعبــة شوي ويبيلها شدة حيل وكل ما أخذتها في بدايــة التخصص يكون أحسن لأن المواد حق التخصص سهلــة في البدايــة وأفضل من بعدين\nأما SE301 فهي لفل 3 وما راح يجيك هولد حتى لو وصلت للسينينر بعكس الفزكس لفل 2 ولازم تخلصها في الجونيــور\n\nوفي الأخير كل شيئ يعتمد عليك وأنت قدها وقدود إن شاء الله\nوراح تدعي لي إذا وصلت جونيور ولا سينيور\nما راح تحس بالفرق إلا متأخر ,\n\nموفق إن شاء الله وفالك A+ في جميع المواد\n🌺 🌺", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/99361/89", "user": "koRaBeKa", "ts": 1292791414000, "tid": 99361, "pn": 89}}', 1292791414000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p900823-me203', 'stk-saleh_ali', 'ME 203', 'srcU', '{"html": "تفضلوا<br>للمدرس سليمان باشا<br><br>​<span data-fid=\"stk-f900823-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f900823-0": {"name": "ME203_syllabus.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203/111993/4", "user": "saleh_ali", "ts": 1315930316000, "tid": 111993, "pn": 4}}', 1315930316000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p740263-me203', 'stk-_student', 'ME 203', 'srcP', '{"html": "ارقام الفقرات في المانيوال مو زي اللي في الكتاب، تزيد او تنقص برقم.<br><br>هذا من شابتر 1 إلى 7<br>[تحميل الملف ME 203 manual solution.rar من هنا](مخزن - مواضيع ومقالات 203 manual solution.rar)<br><br>بقية شابترات<br>مخزن - مواضيع ومقالات Chapters.rar<br><br>وفي المرفق أرقام مسائل الكتاب اقترحها علينا الدكتور، وقال لنا نركز على شابتر 4 و 5 علشان الميجر الأول<br><br>مع تمنياتي للجميع بالتوفيق والنجاح<br><br>​<span data-fid=\"stk-f740263-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f740263-0": {"name": "Extram Problems.pdf", "v": "data:application/pdf;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-203-manual-solution-for-6th-edition/98818/1", "user": "_student", "ts": 1291104272000, "tid": 98818, "pn": 1}}', 1291104272000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
